import{_ as e,o as t,c as s,ag as l}from"./chunks/framework.DjoNWoIY.js";const u=JSON.parse('{"title":"工作原理","description":"","frontmatter":{},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md","lastUpdated":1792519691000}'),i={name:"guide/architecture.md"};function o(d,a,n,c,r,h){return t(),s("div",null,[...a[0]||(a[0]=[l(`<h1 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h1><p>schema-form-vue 把“表单描述”和“组件实现”分开，分成三层：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>schema（你写的字段描述）</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>form 引擎（校验、状态、布局、选项加载）</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>UI 适配器（把字段渲染成具体组件）</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Element Plus / Naive UI / Ant Design Vue / 原生控件</span></span></code></pre></div><h2 id="三层分别做什么" tabindex="-1">三层分别做什么 <a class="header-anchor" href="#三层分别做什么" aria-label="Permalink to &quot;三层分别做什么&quot;">​</a></h2><h3 id="schema" tabindex="-1">schema <a class="header-anchor" href="#schema" aria-label="Permalink to &quot;schema&quot;">​</a></h3><p>用 <code>s.object()</code>、<code>s.string()</code>、<code>s.enum()</code> 等声明字段。schema 里只有语义：</p><ul><li>这个字段叫什么、显示什么 label；</li><li>是否必填、有什么校验；</li><li>默认值、是否可见、是否禁用；</li><li>用哪种输入语义（文本、数字、枚举、日期、富文本……）。</li></ul><p>schema 不引用 Vue 组件，也不依赖具体 UI 库。</p><h3 id="form-引擎" tabindex="-1">form 引擎 <a class="header-anchor" href="#form-引擎" aria-label="Permalink to &quot;form 引擎&quot;">​</a></h3><p><code>@schemavue/form</code> 负责：</p><ul><li>根据 schema 递归渲染字段；</li><li>维护表单值、错误、touched 状态；</li><li>执行校验、条件显示和联动；</li><li>处理布局、数组字段、异步选项；</li><li>把字段状态交给适配器。</li></ul><p>校验和状态逻辑在这里完成，因此同一份 schema 不依赖具体 UI 组件。</p><h3 id="ui-适配器" tabindex="-1">UI 适配器 <a class="header-anchor" href="#ui-适配器" aria-label="Permalink to &quot;UI 适配器&quot;">​</a></h3><p>适配器负责把抽象字段变成具体组件。例如 <code>string</code> 字段在 Element Plus 里是 <code>ElInput</code>，在 shadcn 风格里是原生 <code>input</code>。</p><p>适配器需要提供：</p><ul><li>基本字段组件：文本、多行文本、数字、枚举、布尔、日期；</li><li>表单项容器：Form、FormItem、数组项；</li><li>可选的布局和富文本能力。</li></ul><p>因为适配器的接口是固定的，切换 UI 库时只需要换适配器，schema 和业务代码不用改。</p><h2 id="可选能力" tabindex="-1">可选能力 <a class="header-anchor" href="#可选能力" aria-label="Permalink to &quot;可选能力&quot;">​</a></h2><p>核心包保持轻量，下面这些能力按需安装：</p><table tabindex="0"><thead><tr><th>想要的能力</th><th>安装</th></tr></thead><tbody><tr><td>只读表格</td><td><code>@schemavue/table</code></td></tr><tr><td>HTML 富文本</td><td><code>@schemavue/tiptap</code></td></tr><tr><td>Markdown 富文本</td><td><code>@schemavue/milkdown</code> 或 <code>@schemavue/tiptap-markdown</code></td></tr><tr><td>JSON Schema 互操作</td><td><code>@schemavue/json-schema</code></td></tr><tr><td>多语言文案</td><td><code>@schemavue/locale</code></td></tr></tbody></table><p>不安装富文本编辑器时，富文本字段会退化为普通 textarea；不安装表格包时，表单功能不受影响。</p><h2 id="数据流" tabindex="-1">数据流 <a class="header-anchor" href="#数据流" aria-label="Permalink to &quot;数据流&quot;">​</a></h2><ol><li>用户输入 → 适配器触发字段更新；</li><li>form 引擎写入表单值并重新计算相关字段状态；</li><li>校验结果和可见性变化回到字段；</li><li>字段通过适配器重新渲染。</li></ol><p>适配器只关心“怎么显示、怎么触发更新”，不保存业务状态；因此适配器可以替换，也可以自己实现。</p><h2 id="自定义" tabindex="-1">自定义 <a class="header-anchor" href="#自定义" aria-label="Permalink to &quot;自定义&quot;">​</a></h2><ul><li><strong>自定义字段</strong>：为适配器增加或覆盖一个 widget；</li><li><strong>自定义布局</strong>：使用内置 <code>grid/card/tabs/steps</code>，或基于字段插槽自行组合；</li><li><strong>自定义编辑器</strong>：把任意实现标准字段接口的 Vue 组件接入富文本配置。</li></ul><p>更深入的设计说明在仓库的 <code>docs/design/</code> 中；日常使用不需要阅读。</p>`,27)])])}const m=e(i,[["render",o]]);export{u as __pageData,m as default};
